$('help').onclick=()=>$('guide').hidden=!$('guide').hidden;$('closeGuide').onclick=()=>$('guide').hidden=true;
async function enableMic(){if(audioContext){await audioContext.resume();return}try{micStream=await navigator.mediaDevices.getUserMedia({audio:{echoCancellation:false,noiseSuppression:false,autoGainControl:false}});audioContext=new AudioContext();await audioContext.resume();const source=audioContext.createMediaStreamSource(micStream),analyser=audioContext.createAnalyser();analyser.fftSize=1024;source.connect(analyser);const bins=new Uint8Array(analyser.frequencyBinCount);let baseline=7,streak=0;const detect=()=>{if(!audioContext)return;analyser.getByteFrequencyData(bins);let energy=0;for(let i=3;i<120;i++)energy+=bins[i];energy/=117;baseline=baseline*.995+energy*.005;const blowing=energy>Math.max(15,baseline*1.65);streak=blowing?streak+1:Math.max(0,streak-2);if(streak>=4&&audioContext.state==='running'){addFog(.025);$('hint').textContent='손끝으로 글씨를 남겨보세요'}requestAnimationFrame(detect)};detect();$('sound').setAttribute('aria-pressed','true');$('sound').querySelector('span').textContent='입김 켜짐'}catch{notice('마이크를 사용할 수 없어요. ‘김 서리기’ 버튼으로도 사용할 수 있어요.')}}
