async function enableHands(){if(!stream){notice('손 추적은 카메라 모드에서 사용할 수 있어요.');return}if(handTracker){handEnabled=!handEnabled;setHands();return}if($('hands').disabled)return;$('hands').disabled=true;$('hands').querySelector('span').textContent='손 추적 준비 중';try{const {FilesetResolver,HandLandmarker}=await import('https://cdn.jsdelivr.net/npm/@mediapipe/tasks-vision@0.10.21/+esm');const files=await FilesetResolver.forVisionTasks('https://cdn.jsdelivr.net/npm/@mediapipe/tasks-vision@0.10.21/wasm');handTracker=await HandLandmarker.createFromOptions(files,{baseOptions:{modelAssetPath:'https://storage.googleapis.com/mediapipe-models/hand_landmarker/hand_landmarker/float16/1/hand_landmarker.task'},runningMode:'VIDEO',numHands:1});handEnabled=true;setHands();track()}catch{notice('손 추적을 불러오지 못했어요. 화면을 직접 문질러 사용할 수 있어요.');$('hands').querySelector('span').textContent='손 추적 다시 시도'}finally{$('hands').disabled=false}}
