function track(t=0){requestAnimationFrame(track);if(!handEnabled||video.readyState<2||t-lastFrame<65)return;lastFrame=t;pen.clearRect(0,0,width,height);try{const result=handTracker.detectForVideo(video,performance.now()),hand=result.landmarks?.[0];if(!hand){lastHand=null;return}const distance=(a,b)=>Math.hypot(a.x-b.x,a.y-b.y);const extended=[8,12,16,20].map(tip=>distance(hand[tip],hand[0])>distance(hand[tip-2],hand[0])*1.15);const open=extended.every(Boolean),writing=extended[0]&&!extended[1]&&!extended[2];if(!open&&!writing){lastHand=null;return}const point=position(open?hand[9]:hand[8]),radius=open?Math.min(130,Math.max(45,distance(position(hand[5]),position(hand[17]))*.8)):14;if(lastHand&&lastHand.open===open&&distance(lastHand,point)<width*.25)erase(lastHand,point,radius);else erase(point,point,radius);lastHand={...point,open};pen.beginPath();pen.arc(point.x,point.y,open?radius:7,0,Math.PI*2);pen.strokeStyle='#fff9';pen.lineWidth=1.5;pen.stroke();$('hint').textContent=open?'손바닥으로 유리를 닦고 있어요':'검지로 마음을 쓰고 있어요'}catch{handEnabled=false;setHands();notice('손 추적이 중단되었어요. 화면을 직접 문질러 주세요.')}}
